/// Brazilian municipalities published by the IBGE, by state, in the pt-BR collation order the JavaScript package returns.
fn municipalities_table() -> &'static runtime::Dataset {
	static TABLE: std::sync::OnceLock<runtime::Dataset> = std::sync::OnceLock::new();

	TABLE.get_or_init(|| runtime::Dataset::new(MUNICIPALITIES_ROWS, MUNICIPALITIES_GROUPS, MUNICIPALITIES_ORDER))
}

/// Reads one dataset row as a municipality.
pub fn row_to_municipality(row: runtime::Row) -> Municipality {
	return Municipality { code: row[2 as usize].to_string(), name: row[1 as usize].to_string(), state_code: row[0 as usize].to_string() };
}

/// Returns Brazilian municipalities published by the IBGE, optionally filtered by state.
///
/// If `stateCode` is provided, only municipalities of that state are returned. If it is
/// omitted, every municipality of every state is returned, sorted with `localeCompare` in the
/// "pt-BR" locale so accented names land where a Brazilian reader expects them. Every per-state
/// list is sorted the same way.
///
/// Only an omitted (or `undefined`) `stateCode` asks for the full list: any other value that is
/// not a known state code, `null` and `""` included, returns `[]`.
///
/// The state code is matched exactly, case included: `getMunicipalities("sp")` returns `[]` where
/// `getMunicipalities("SP")` returns the 645 São Paulo municipalities.
///
/// @see Official: https://servicodados.ibge.gov.br/api/docs/localidades
pub fn get_municipalities(state_code: Option<&str>) -> Vec<Municipality> {
	let mut municipalities: Vec<Municipality> = vec![];
	let mut rows: Vec<runtime::Row> = runtime::data_all(municipalities_table());
	if state_code.is_some() {
		rows = runtime::data_rows(municipalities_table(), &state_code.clone().unwrap());
	}
	for row in rows {
		municipalities.push(row_to_municipality(row));
	}
	return municipalities;
}
